"""Seventeen missing modules: original staged manuscripts; no database access."""
from pathlib import Path
from uuid import uuid5,NAMESPACE_URL

# Correct choices are authored first, then rotated reproducibly by the builder.
# Texts are fictional teaching sources, not administrative/medical/legal advice.
MODULES=[
dict(id='a2-05',title='A routine health appointment',
 reading='Nora téléphone au cabinet pour un rendez-vous de routine. Elle préfère mercredi matin, mais le premier créneau proposé est jeudi à quinze heures. Elle travaille jeudi après-midi. La secrétaire lui propose alors vendredi à neuf heures et lui demande de confirmer son numéro directement au cabinet. Nora accepte vendredi. Elle veut seulement organiser une consultation ; elle ne demande pas de diagnostic par téléphone. Dans cet exercice, aucun numéro ni symptôme personnel ne doit être communiqué.',
 grammar='Polite requests use a conditional chunk such as Je voudrais; availability and constraints can be stated in the present. Distinguish the rejected slot from the accepted one.',
 model='Je voudrais un rendez-vous vendredi matin.',translation='I would like an appointment on Friday morning.',
 question='Which appointment does Nora accept?',choices=['Friday at nine','Thursday at three','Wednesday morning'],
 grammar_question='Which request politely asks for an appointment?',grammar_choices=['Je voudrais un rendez-vous.','Je voulais dire au revoir.','Je viens de quitter le cabinet.'],
 script='Secrétaire : Vendredi à neuf heures, est-ce que cela vous convient ? Nora : Oui. C’est au cabinet habituel ? Secrétaire : Oui, mais l’entrée est dans la petite cour. Nora : Très bien, vendredi à neuf heures, par la cour. Je vous remercie.',
 listen_question='What extra detail does Nora confirm?',listen_choices=['The entrance is through the courtyard','The appointment is Thursday','The consultation is online'],
 cross_question='Which summary keeps the final arrangement?',cross_choices=['Friday at nine, with the courtyard entrance','Thursday at three, at a new address','Wednesday, by video'],quote='par la cour',quote_prompt='Copy the exact three-word phrase Nora uses for the entrance.',
 words=[('le premier créneau proposé','the first proposed time slot','Le premier horaire offert pour le rendez-vous.'),('une consultation de routine','a routine consultation','Un rendez-vous ordinaire, sans caractère urgent dans cette situation.'),('l’entrée dans la petite cour','the entrance in the small courtyard','L’accès indiqué dans cette petite cour.')],
 transfer='Write 80–100 French words as an exchange arranging a routine appointment. Decline one incompatible slot, accept another and confirm the place. Use invented details only; do not give medical advice. With the Tutor as receptionist, ask a clarification question and repeat the final arrangement.'),
dict(id='a2-06',title='Move a picnic and apologise clearly',
 reading='Léa a invité trois amis à un pique-nique samedi à midi. La météo annonce de fortes pluies. Elle propose de se retrouver chez elle à treize heures, sans changer le jour. Hugo répond qu’il peut venir, mais seulement à partir de quatorze heures. Léa lui dit de les rejoindre plus tard : les autres commenceront à treize heures. Elle s’excuse pour ce changement et demande à chacun de confirmer. Son message ne dit pas que le pique-nique est reporté au dimanche.',
 grammar='Use parce que for a reason and mais for a contrasting constraint. À partir de sets an earliest time; it does not change everyone’s arrangement.',
 model='On se retrouve chez moi parce qu’il va pleuvoir.',translation='We are meeting at my place because it is going to rain.',
 question='What changes for the whole group?',choices=['The place and the starting time','The day becomes Sunday','Everyone must arrive at two'],
 grammar_question='Which connector introduces the reason in the model?',grammar_choices=['parce que','mais','ou'],
 script='Léa : Désolée pour le changement. On commence samedi à treize heures chez moi. Hugo : Je finis à treize heures trente ; je peux arriver vers quatorze heures. Léa : Pas de problème, rejoins-nous après. Apporte seulement ce que tu avais prévu.',
 listen_question='What should Hugo bring?',listen_choices=['What he had already planned','Nothing at all','An extra table'],
 cross_question='Which reply avoids a new misunderstanding?',cross_choices=['I will join you around two; the others start at one','I will see everyone on Sunday','We all start at two'],quote='vers quatorze heures',quote_prompt='Copy Hugo’s exact approximate arrival-time phrase.',
 words=[('s’excuser pour ce changement','to apologise for this change','Présenter des excuses à propos de la modification annoncée.'),('rejoindre le groupe plus tard','to join the group later','Arriver après le début de la rencontre.'),('confirmer sa présence au pique-nique','to confirm attendance at the picnic','Dire clairement que l’on participera à cette rencontre.')],
 transfer='Write 80–110 French words inviting an imaginary friend, changing one detail because of a practical problem and apologising. Keep the date and times consistent. Role-play a reply from a friend who can arrive late, and confirm what changes for that friend only.'),
dict(id='a2-07',title='Repair a parcel-pickup misunderstanding',
 reading='Un avis indique que le colis de Malik est disponible au point relais de la rue des Écoles jusqu’à samedi. Malik pense d’abord qu’il doit aller au bureau de poste. En relisant, il remarque le nom du commerce et vérifie son horaire. Le magasin ferme à dix-neuf heures en semaine et à dix-sept heures le samedi. L’avis demande un justificatif pour retirer le colis. Les détails de cette situation sont fictifs : il faut toujours vérifier les instructions de son propre avis.',
 grammar='Jusqu’à gives an end point; avant gives a boundary. Use est-ce que or a short confirmation question to check a detail instead of silently assuming it.',
 model='Est-ce que le magasin ferme à dix-sept heures samedi ?',translation='Does the shop close at five on Saturday?',
 question='Where should Malik collect the parcel?',choices=['At the named collection shop','At any post office','At the station'],
 grammar_question='What does jusqu’à samedi express here?',grammar_choices=['The stated availability end point','An opening time every Saturday','A requirement to wait until Saturday'],
 script='Malik : Pardon, j’ai compris dix-neuf heures pour samedi. Employée : Dix-neuf heures en semaine, mais dix-sept heures le samedi. Malik : Donc samedi, je dois venir avant dix-sept heures ? Employée : Oui, c’est cela.',
 listen_question='Which misunderstanding is corrected?',listen_choices=['Saturday’s closing time','The sender’s name','The number of parcels'],
 cross_question='What is a useful next step?',cross_choices=['Check the required document and come before Saturday’s closing','Assume the post office keeps the parcel','Wait until Saturday at nineteen hours'],quote='avant dix-sept heures',quote_prompt='Copy Malik’s exact phrase giving the Saturday arrival boundary.',
 words=[('le point relais indiqué','the indicated collection point','Le commerce nommé sur l’avis pour récupérer le colis.'),('relire l’avis de passage','to reread the delivery notice','Lire de nouveau le document laissé au destinataire.'),('vérifier l’heure de fermeture','to check the closing time','S’assurer de l’heure à laquelle le commerce ferme.')],
 transfer='Write a 90-word clarification exchange about a fictional parcel notice. Include the place, a weekday/weekend distinction and one corrected assumption. Ask the Tutor to state two similar times and confirm the right one before summarising. Do not use real parcel numbers or identification details.'),
dict(id='a2-08',title='A2 review: solve a day-trip disruption',
 reading='Inès organise une sortie à Nantes avec une amie. Elles ont prévu de prendre le train de huit heures et de visiter un musée à dix heures. Le matin, leur train est supprimé. Le suivant arrive à dix heures trente. Le musée leur confirme que leur billet fictif permet une entrée jusqu’à midi. Elles décident donc de garder la visite et de déjeuner plus tard. Elles envoient un message à l’ami qui devait les retrouver devant le musée à dix heures pour lui proposer onze heures.',
 grammar='Connect events with d’abord, puis and donc. Keep an earlier plan separate from the revised arrangement; a consequence is not another cause.',
 model='Le train est supprimé, donc nous arriverons plus tard.',translation='The train is cancelled, so we will arrive later.',
 question='Why can they keep the museum visit?',choices=['The stated ticket permits entry until noon','The train arrives before ten','The museum is free all evening'],
 grammar_question='Which word marks a consequence in the model?',grammar_choices=['donc','parce que','avant'],
 script='Inès : Nous arriverons à la gare à dix heures trente. Ami : Je vous attends toujours à dix heures devant le musée ? Inès : Non, retrouvons-nous à onze heures. Nous déjeunerons après la visite. Ami : D’accord, je note onze heures.',
 listen_question='What is the new meeting time?',listen_choices=['Eleven','Ten','Noon'],
 cross_question='Which sequence matches the plan?',cross_choices=['Arrival, meeting at eleven, visit, lunch','Lunch at ten, then the original train','Cancel the visit and meet at ten'],quote='après la visite',quote_prompt='Copy the exact phrase indicating when they will have lunch.',
 words=[('garder la visite prévue','to keep the planned visit','Maintenir la visite malgré le changement de trajet.'),('proposer une nouvelle heure','to suggest a new time','Demander un horaire de rencontre différent.'),('un train supprimé ce matin','a train cancelled this morning','Un départ annoncé qui n’aura pas lieu ce matin.')],
 transfer='Without copying the model, write 100–120 French words explaining a different fictional day-trip problem, a constraint and a consistent revised plan. Add a reply checking two details. Retell it orally, then answer an unexpected clarification from the Tutor. Review sequence, times, reason and consequence; this is a formative review, not an A2 award.'),
dict(id='b1-05',title='Keep pronoun reference clear in a shared project',
 reading='Julie prête son ordinateur à Karim pour préparer une affiche avec Ana. Quand Ana arrive, il lui explique que Julie en a besoin avant dix-sept heures. Ana propose de terminer le texte sur son propre appareil et de l’envoyer ensuite à Karim. Celui-ci accepte, mais demande que le fichier reste modifiable. Le soir, Julie remercie Karim de lui avoir rendu l’ordinateur à temps. Dans ce récit, l’ordinateur de Julie et l’appareil d’Ana ne doivent pas être confondus ; le pronom le de l’envoyer renvoie au texte, pas à un appareil.',
 grammar='Resolve pronouns from grammar and discourse, not simply from the nearest noun. Celui-ci can resume a named participant; en avoir besoin resumes a complement introduced by de.',
 model='Ana termine le texte, puis elle l’envoie à Karim.',translation='Ana finishes the text, then sends it to Karim.',
 question='What will Ana send to Karim?',choices=['The text','Julie’s computer','Her own computer'],
 grammar_question='What does l’ replace in the model?',grammar_choices=['le texte','Ana','Karim'],
 script='Karim : Julie a besoin de son ordinateur à dix-sept heures. Ana : Je peux finir sur le mien. Je t’envoie le texte, mais je garde aussi une copie. Karim : Très bien ; envoie-le dans un format que je pourrai modifier.',
 listen_question='What condition does Karim add?',listen_choices=['The text must remain editable','Ana must keep Julie’s computer','No copy may be kept'],
 cross_question='Which clarification preserves the roles?',cross_choices=['Ana uses her own device; Julie gets hers back','Julie sends her computer to Ana','Karim keeps both devices overnight'],quote='une copie',quote_prompt='Copy the two-word phrase naming what Ana also keeps.',
 words=[('un fichier qui reste modifiable','a file that remains editable','Un document dont le contenu peut encore être changé.'),('rendre l’ordinateur à temps','to return the computer on time','Restituer l’appareil avant l’heure convenue.'),('garder une copie du texte','to keep a copy of the text','Conserver un exemplaire supplémentaire du document.')],
 transfer='Write 140–170 French words describing three people sharing two objects and a document. Keep the reference chain clear; replace an ambiguous pronoun with a name. Explain the sequence aloud and ask the Tutor to identify who owns what before you confirm.'),
dict(id='b1-06',title='Follow a local news discussion without exaggerating',
 reading='Un journal local annonce que la piscine municipale ouvrira plus tôt deux jours par semaine pendant un mois d’essai. La mairie dit vouloir observer la demande des personnes qui travaillent le matin. Un habitant s’en réjouit, mais rappelle que le bus arrive après la nouvelle ouverture. Une association demande aussi si le tarif restera identique. L’article ne donne pas encore la réponse. Le journaliste précise qu’une réunion aura lieu après l’essai. Dire que les nouveaux horaires seront définitifs, ou que le prix a augmenté, irait au-delà de l’information publiée.',
 grammar='Use reported statements to distinguish an announcement, a question and an unanswered point. Pendant un mois limits the trial; après l’essai locates the later review.',
 model='Le journal annonce que l’essai durera un mois.',translation='The newspaper reports that the trial will last one month.',
 question='Which point is not answered in the article?',choices=['Whether the price stays the same','Whether there will be a trial','Whether the pool is municipal'],
 grammar_question='Which report preserves the temporary nature?',grammar_choices=['Les horaires seront testés pendant un mois.','Les horaires sont définitivement adoptés.','L’essai est déjà terminé.'],
 script='Journaliste : Vous soutenez cette ouverture ? Habitante : Oui, si l’accès suit. Pour moi, gagner une heure à la piscine ne sert pas beaucoup si le premier bus arrive trop tard. Je ne demande pas de supprimer l’essai ; je demande qu’on regarde aussi le trajet.',
 listen_question='What is the inhabitant’s position?',listen_choices=['Support the trial while checking transport access','Cancel every early opening','Claim the bus timetable has already changed'],
 cross_question='Which headline would be misleading?',cross_choices=['Early opening permanently adopted','One-month trial announced','Transport access questioned'],quote='le trajet',quote_prompt='Copy the short phrase naming the additional issue to examine.',
 words=[('un mois d’essai annoncé','an announced one-month trial','Une période temporaire prévue pour tester le changement.'),('une question restée sans réponse','a question left unanswered','Un point sur lequel aucune réponse n’a encore été donnée.'),('regarder aussi le trajet','to examine the journey as well','Prendre en compte le déplacement nécessaire pour accéder au service.')],
 transfer='Write 150–180 French words summarising the news for a classmate. Separate facts, a resident’s opinion and one unanswered question. Role-play a short interview with the Tutor and reformulate the reply without changing a conditional opinion into an unconditional one.'),
dict(id='b1-07',title='Adapt a practical request to two recipients',
 reading='Après avoir oublié un sac dans une salle de cours, Marc écrit d’abord à une amie : « Tu as vu mon sac bleu ? Je crois que je l’ai laissé près de la fenêtre. » Il doit ensuite contacter l’accueil de l’université. Il reprend les mêmes faits, mais ajoute le numéro de la salle, le moment du cours et une demande précise. Il évite d’affirmer que le personnel a déplacé le sac : il ne le sait pas. Son objectif est d’aider à vérifier, pas de raconter tous les détails de sa journée ni de reprocher une faute à quelqu’un.',
 grammar='Adapt address and request forms to the recipient while keeping factual content stable. Je crois que marks uncertainty; pourriez-vous frames a polite request rather than an accusation.',
 model='Pourriez-vous vérifier si un sac bleu a été retrouvé ?',translation='Could you check whether a blue bag has been found?',
 question='What should change between the two messages?',choices=['Address, useful identifying details and request form','The colour of the bag','An uncertain fact into a proven accusation'],
 grammar_question='Which phrase preserves uncertainty about the location?',grammar_choices=['Je crois l’avoir laissé près de la fenêtre.','Vous l’avez certainement déplacé.','Je sais que vous l’avez pris.'],
 script='Accueil : Pouvez-vous préciser la salle et l’heure ? Marc : Salle douze, après le cours de neuf heures. Je crois avoir laissé le sac près de la fenêtre. Accueil : Merci. Nous allons vérifier ; cela ne signifie pas encore qu’il a été retrouvé.',
 listen_question='What does the reception desk commit to?',listen_choices=['Checking the information','Confirming the bag is found','Replacing the bag immediately'],
 cross_question='Which follow-up is most accurate?',cross_choices=['Reception will check; recovery is not yet confirmed','The bag has certainly been found','Reception admits taking it'],quote='Nous allons vérifier',quote_prompt='Copy the reception desk’s exact three-word commitment.',
 words=[('préciser la salle du cours','to specify the classroom','Donner le numéro ou le nom de la salle concernée.'),('une demande précise à l’accueil','a specific request to reception','Une question qui indique clairement la vérification souhaitée.'),('un objet peut-être retrouvé','an item that may have been found','Un objet dont la récupération reste incertaine.')],
 transfer='Write a 60-word informal message and a 110-word formal request about a fictional lost object. Preserve the same facts and uncertainty. Explain aloud why you changed the address, detail and closing, then answer the Tutor’s follow-up as reception. Do not include real identity documents.'),
dict(id='b1-08',title='B1 review: organise a volunteer event under constraints',
 reading='Une association prépare une collecte de livres samedi. La salle prévue n’est disponible que jusqu’à seize heures, alors que plusieurs bénévoles ne peuvent arriver qu’à quinze heures. Salomé propose de commencer le tri vendredi soir et de réserver samedi aux dépôts. Paul préfère chercher une autre salle, mais aucune disponibilité n’est confirmée. Le groupe choisit provisoirement la solution de Salomé, à condition que deux personnes puissent venir vendredi. Une décision finale est attendue jeudi. Ce compromis n’est donc ni une annulation ni une réservation certaine d’une nouvelle salle.',
 grammar='Distinguish a proposal, a provisional choice and a confirmed arrangement. À condition que adds a requirement; provisoirement limits the commitment.',
 model='Nous commencerons vendredi si deux bénévoles sont disponibles.',translation='We will start on Friday if two volunteers are available.',
 question='What must be checked before the provisional plan is confirmed?',choices=['Two volunteers are available Friday','A new hall is already booked','The collection must be cancelled'],
 grammar_question='Which sentence keeps the condition realistic and open?',grammar_choices=['Si deux bénévoles viennent, nous commencerons vendredi.','Si deux bénévoles viendront, nous commencerons vendredi.','Si deux bénévoles viennent, ils étaient déjà là.'],
 script='Paul : Je cherche encore une salle, mais je ne peux rien promettre. Salomé : Gardons donc le premier plan jusqu’à jeudi. Si tu trouves mieux avant, nous comparerons les horaires et le transport. Paul : D’accord ; je vous donne une réponse, même si ma recherche n’aboutit pas.',
 listen_question='What does Paul promise?',listen_choices=['An update even if the search fails','A guaranteed new room','To cancel the first plan now'],
 cross_question='Which summary preserves the decision status?',cross_choices=['A conditional plan remains pending until Thursday','A different room is confirmed','All preparation moves to Sunday'],quote='jusqu’à jeudi',quote_prompt='Copy the phrase giving the temporary decision horizon.',
 words=[('un choix encore provisoire','a choice that is still provisional','Une décision qui peut encore être modifiée.'),('comparer les horaires et le transport','to compare times and transport','Examiner ensemble les heures et les moyens de déplacement.'),('une recherche qui n’aboutit pas','a search that does not succeed','Une démarche qui ne donne pas le résultat souhaité.')],
 transfer='Write 170–200 French words proposing a solution to a different community-event constraint. Explain two options, a reasoned provisional choice and the information still needed. Give an oral update, answer an objection from the Tutor and revise one unclear commitment. This cross-skill review does not award B1.'),
dict(id='b2-06',title='Build a reasoned position on a university attendance policy',
 reading='Une université propose d’enregistrer les cours magistraux tout en maintenant certaines séances obligatoires. Les partisans du projet soulignent que les enregistrements aideraient les étudiants salariés et permettraient de reprendre une explication difficile. Des enseignants craignent cependant qu’une offre identique pour toutes les séances ne réduise les occasions de discussion. Leur objection ne prouve pas que l’enregistrement ferait baisser la participation ; elle identifie un risque à examiner. Une proposition intermédiaire distingue les exposés destinés à transmettre des connaissances et les séances consacrées à discuter des problèmes. Cette distinction peut être utile, mais elle ne doit pas devenir une étiquette commode qui dispense d’expliquer le rôle pédagogique de chaque séance. Une argumentation solide doit donc préciser ce qu’elle cherche à rendre accessible et les interactions qu’elle souhaite préserver.',
 grammar='Concession acknowledges the force of a consideration without granting the opponent’s whole conclusion. Use certes… mais, bien que and conditional claims with clear scope; an identified risk is not an observed effect.',
 model='Bien que les enregistrements facilitent l’accès, ils ne remplacent pas toute interaction.',translation='Although recordings facilitate access, they do not replace every interaction.',
 question='What is a justified middle position?',choices=['Differentiate formats by their explained teaching purpose','Assume every recording reduces participation','Make every session identical without justification'],
 grammar_question='What does the concession in the model preserve?',grammar_choices=['An access benefit alongside an interaction limitation','A denial of every access benefit','Proof that all interaction is impossible'],
 script='Étudiante : Je ne demande pas que chaque discussion soit transformée en vidéo. Je demande que mon absence à un exposé ne m’empêche pas d’accéder à son contenu. Enseignant : Je peux accepter cette distinction, à condition qu’on examine aussi ce que les étudiants ne pourront pas demander après coup. Étudiante : Alors évaluons les deux aspects, plutôt que de traiter l’accès et l’échange comme deux objectifs incompatibles.',
 listen_question='What compromise emerges?',listen_choices=['Evaluate access and opportunities for questions together','Replace every discussion by a video','Treat access as irrelevant'],
 cross_question='Which objection deserves a substantive response?',cross_choices=['How absent students can ask follow-up questions','Whether recordings have any possible use at all','A claim that the student rejects all interaction'],quote='deux objectifs incompatibles',quote_prompt='Copy the exact phrase naming the false opposition rejected by the student.',
 words=[('préserver les occasions de discussion','to preserve opportunities for discussion','Maintenir les moments où des questions peuvent être débattues.'),('répondre à une objection de fond','to answer a substantive objection','Traiter une difficulté qui touche réellement l’argument.'),('justifier le format de chaque séance','to justify the format of each session','Expliquer pourquoi une organisation convient à son objectif pédagogique.')],
 transfer='Write 280–330 French words for the university council. State a qualified position, compare two arrangements, support each claim from the dossier and answer a substantive counterargument. Revise a false opposition and one overstatement. Present a three-minute defence and ask the Tutor to challenge the strongest assumption.'),
dict(id='b2-07',title='Negotiate shared workspace constraints',
 reading='Deux associations doivent partager une salle pendant six semaines. L’une organise des permanences confidentielles ; l’autre prépare un spectacle avec du matériel encombrant. La première propose de garder les après-midi, mais la seconde ne dispose de bénévoles qu’en fin de journée. Un simple partage égal du nombre d’heures ne résoudrait donc pas le conflit : toutes les heures ne sont pas également utilisables, et le stockage réduit aussi l’espace disponible. La responsable demande à chaque équipe de distinguer ce qui est indispensable de ce qui serait seulement préférable. Les deux équipes acceptent de tester un horaire aménagé pendant une semaine, sans considérer cette acceptation comme un accord définitif. Le bilan doit inclure la confidentialité, le temps de remise en état et l’accès au matériel.',
 grammar='Use conditional proposals to explore alternatives without prematurely committing. Distinguer indispensable/préférable prevents a preference being presented as a non-negotiable constraint.',
 model='Nous pourrions avancer la répétition si la salle était remise en état avant dix-sept heures.',translation='We could bring the rehearsal forward if the room were restored before five.',
 question='Why is equal hourly allocation insufficient?',choices=['Usable times, confidentiality and storage differ','Both groups have identical needs','Storage has no effect on access'],
 grammar_question='What does the model express?',grammar_choices=['A conditional possible arrangement','An already completed agreement','A promise with no condition'],
 script='Responsable : Pourriez-vous laisser le matériel dans l’armoire ? Équipe spectacle : À condition que nous puissions y accéder sans interrompre les permanences. Équipe accueil : Nous pouvons réserver un passage avant l’ouverture, mais pas pendant un entretien. Responsable : Notons cette limite et testons-la lundi ; si elle ne fonctionne pas, nous rouvrirons la discussion.',
 listen_question='Which limit is explicitly accepted for the trial?',listen_choices=['No equipment access during an interview','Unrestricted access throughout every interview','The cabinet is never accessible'],
 cross_question='Which follow-up preserves room for renegotiation?',cross_choices=['Review the Monday trial against the written limits','Call the trial a final permanent agreement','Ignore restoration time'],quote='nous rouvrirons la discussion',quote_prompt='Copy the exact phrase describing what happens if the trial fails.',
 words=[('la remise en état de la salle','restoring the room for use','L’action de rendre la salle utilisable après une activité.'),('une contrainte réellement indispensable','a genuinely essential constraint','Une condition nécessaire au fonctionnement de l’activité.'),('rouvrir la discussion après l’essai','to reopen discussion after the trial','Reprendre la négociation à partir des résultats du test.')],
 transfer='Prepare a 240-word written agreement distinguishing fixed constraints, negotiable preferences, trial duration and review criteria. Then negotiate for four minutes with the Tutor, concede one preference, reject one impractical option politely and summarise the provisional agreement without adding commitments.'),
dict(id='b2-08',title='B2 review: compare an energy-saving proposal and objections',
 reading='Dans un immeuble fictif, un groupe propose de réduire légèrement le chauffage des espaces communs et d’utiliser l’économie annoncée pour améliorer l’isolation. Le calcul repose sur une estimation, non sur une mesure réalisée dans cet immeuble. Une résidente soutient l’objectif, mais demande comment seront pris en compte les usages différents du hall et de la salle collective. Un autre habitant conteste l’ordre des travaux : selon lui, isoler d’abord éviterait de faire supporter immédiatement la contrainte aux usagers. Le groupe répond que le financement doit justement être trouvé. Aucun de ces arguments ne suffit à prouver que le projet est bon ou mauvais dans toutes ses dimensions. Il faut distinguer le montant espéré, la répartition des effets et la possibilité de réviser l’essai à partir de mesures locales.',
 grammar='Keep a conditional forecast distinct from a measured result; attribute reported views explicitly. Selon lui is attribution, not endorsement. A counterargument must address the reasoning rather than its author.',
 model='L’économie serait utile, encore faudrait-il vérifier le calcul localement.',translation='The saving would be useful, but the calculation would still need local verification.',
 question='What evidence is missing?',choices=['A local measurement supporting the estimate','Any stated purpose for the money','Any resident objection'],
 grammar_question='Which formulation keeps the evidential limit?',grammar_choices=['L’économie est estimée, non encore mesurée ici.','L’économie est garantie dans tous les cas.','Les résidents ont tous confirmé le calcul.'],
 script='Résidente : Je ne refuse pas une économie, mais je veux savoir qui devra changer ses habitudes. Porte-parole : C’est pourquoi nous proposons un essai limité et un relevé des usages. Habitant : Un relevé ne vaut que si nous décidons aussi ce qui nous ferait arrêter ou modifier l’essai. Porte-parole : Convenons de ces critères avant de commencer.',
 listen_question='What additional requirement is accepted?',listen_choices=['Define modification or stop criteria before the trial','Begin without any review rule','Treat every habit as identical'],
 cross_question='Which recommendation integrates the dossier?',cross_choices=['Measure locally, examine distribution and agree review criteria','Guarantee the estimated saving','Ignore objections because the goal is desirable'],quote='avant de commencer',quote_prompt='Copy the phrase indicating when the criteria must be agreed.',
 words=[('la répartition des effets attendus','the distribution of expected effects','La manière dont les conséquences prévues toucheraient les personnes.'),('un calcul à vérifier localement','a calculation to verify locally','Une estimation qui doit être confrontée à la situation réelle du lieu.'),('des critères convenus avant l’essai','criteria agreed before the trial','Des repères d’évaluation définis avant le début du test.')],
 transfer='Write a 300–360-word recommendation on a new fictional collective-resource problem. Integrate evidence limits, a distributional objection and a conditional decision. Give a four-minute oral defence with follow-up challenges. Assess comprehension, attribution, counterargument, coherence and language separately; do not turn this module review into a B2 certificate.'),
dict(id='c1-05',title='Track shifting qualifications in a research meeting',
 reading='Un comité examine une enquête sur l’usage des bibliothèques. Le rapport distingue les réponses recueillies en ligne et celles obtenues à l’accueil, sans prétendre que leur réunion produit un échantillon représentatif. La présidente souhaite néanmoins publier rapidement des tendances pour éclairer le prochain budget. Le chercheur accepte cette utilité pratique, à condition que les différences de recrutement restent visibles. Une représentante des usagers ajoute que les personnes qui ne fréquentent plus la bibliothèque ne sont présentes dans aucun des deux groupes. Cette remarque ne réfute pas les réponses obtenues ; elle délimite les questions auxquelles elles peuvent contribuer. La discussion se déplace ainsi de la qualité d’un chiffre isolé vers la relation entre population observée, décision envisagée et portée de la communication publique.',
 grammar='Track the scope of qualifications and changes of stance. À condition que limits acceptance; néanmoins introduces a practical choice despite a methodological limit, not the disappearance of that limit.',
 model='Le rapport peut éclairer la décision, pourvu que sa portée ne soit pas exagérée.',translation='The report can inform the decision provided its scope is not exaggerated.',
 question='What does the users’ representative add?',choices=['Non-users are absent from both recruitment channels','All collected responses are worthless','The combined sample is proved representative'],
 grammar_question='Which formulation preserves the committee’s qualified acceptance?',grammar_choices=['Utiliser les tendances tout en explicitant les limites du recrutement.','Publier sans réserve puisque le budget est urgent.','Attendre une certitude parfaite avant toute décision.'],
 script='Présidente : Je proposais une synthèse unique, mais j’entends le problème. Chercheur : Une synthèse est possible ; c’est l’effacement des deux modes de recrutement qui serait trompeur. Représentante : Et il faut nommer ceux que nous n’avons pas entendus. Présidente : Alors publions deux séries accompagnées d’une question ouverte sur les non-usagers. Chercheur : Cela précise la portée, sans transformer l’enquête en ce qu’elle n’est pas.',
 listen_question='How does the chair’s position change?',listen_choices=['She moves from a single undifferentiated synthesis to a qualified presentation','She withdraws every practical use of the survey','She claims all non-users have been consulted'],
 cross_question='Which mediation preserves the speakers’ convergence?',cross_choices=['They seek a useful presentation that keeps sampling limits visible','They agree representativeness has been demonstrated','They disagree on whether any response was collected'],quote='ceux que nous n’avons pas entendus',quote_prompt='Copy the representative’s exact phrase identifying the absent voices.',
 words=[('les modes de recrutement des répondants','the ways respondents were recruited','Les procédés par lesquels les participants ont été sollicités.'),('délimiter la portée d’une enquête','to delimit a survey’s scope','Préciser les conclusions auxquelles une enquête peut contribuer.'),('des voix absentes du dispositif','voices absent from the process','Des points de vue qui n’ont pas été recueillis par la méthode choisie.')],
 transfer='Listen without the transcript, map each speaker’s initial stance and later qualification, then compare with the text. Write a 330–400-word briefing separating convergence, unresolved limits and a justified decision. Mediate the meeting orally with the Tutor changing one stakeholder’s priority. Label the source as a scripted dialogue performed by synthetic speech, not authentic multi-speaker audio.'),
dict(id='c1-07',title='Use reformulation and emphasis to qualify a commitment',
 reading='Une cheffe de projet doit expliquer un retard sans en minimiser les effets ni promettre une date qu’elle ne maîtrise pas. Son premier brouillon dit : « Nous livrerons dès que possible. » Cette formule peut paraître rassurante, mais elle ne fournit ni étape vérifiable ni limite de l’engagement. Le second précise que les tests commenceront lundi si le composant attendu arrive vendredi, puis qu’un point sera envoyé mardi même en l’absence de livraison. La responsabilité de l’information est ainsi distinguée de la maîtrise de tous les événements. À l’oral, l’insistance sur « même en l’absence de livraison » peut rendre cette différence perceptible. Une prosodie expressive ne remplace pourtant pas la précision du contenu : elle doit soutenir une distinction déjà intelligible, non produire une certitude que les mots refusent.',
 grammar='Separate commitment to an action under one’s control from a conditional outcome. Même en l’absence de maintains the information commitment across alternatives; reformulation must preserve this modal structure.',
 model='Nous confirmerons l’état des tests mardi, même si la livraison n’a pas eu lieu.',translation='We will confirm the test status on Tuesday even if delivery has not taken place.',
 question='Which commitment is independent of the delivery condition?',choices=['Sending the Tuesday update','Completing every test Monday','Guaranteeing Friday delivery'],
 grammar_question='What does même si preserve in the model?',grammar_choices=['The update will be sent under either delivery outcome','The update depends on successful delivery','Delivery is guaranteed'],
 script='Cliente : Donc vous me garantissez une livraison mardi ? Cheffe de projet : Non : je garantis un point mardi. Si le composant arrive vendredi, nous lancerons les tests lundi. Cliente : Et s’il n’arrive pas ? Cheffe de projet : Vous aurez tout de même un état précis et la prochaine étape ; je ne veux pas transformer cette obligation d’information en promesse de livraison.',
 listen_question='What misunderstanding is repaired?',listen_choices=['An information deadline was heard as a delivery guarantee','The client denied wanting any information','Testing had already finished'],
    cross_question='Which oral strategy preserves precision?',cross_choices=['Contrast point mardi with livraison mardi, then restate the condition','Stress mardi to imply guaranteed delivery','Replace every condition by a confident slogan'],quote='promesse de livraison',quote_prompt='Copy the phrase naming the commitment explicitly rejected.',
 words=[('un engagement dont on maîtrise l’exécution','a commitment whose execution one controls','Une obligation portant sur une action que l’on peut effectivement réaliser.'),('une étape réellement vérifiable','a genuinely verifiable step','Une action dont l’accomplissement peut être constaté.'),('préserver la portée de la condition','to preserve the condition’s scope','Maintenir ce qui dépend précisément de l’hypothèse formulée.')],
 transfer='Prepare a 300-word professional update with a controlled commitment and an uncertain outcome. Record two versions, changing pauses and emphasis while preserving the facts. Explain which contrast you wanted the listener to hear. Ask the Tutor to misinterpret the promise and repair it. A transcript cannot evaluate prosody; human listening is required for that criterion.'),
dict(id='c1-08',title='C1 review: mediate a cultural-service decision',
 reading='Un centre culturel veut déplacer une partie de ses ateliers vers un format hybride. Une note budgétaire anticipe une baisse des déplacements ; un bilan pédagogique souligne que certaines activités reposent sur la manipulation collective d’objets. Les documents ne mesurent donc pas exactement le même résultat. La directrice demande une synthèse qui permette une décision sans réduire ces dimensions à un indicateur unique. Une association d’usagers souhaite aussi que soient distinguées la disponibilité d’un accès numérique et la capacité effective à s’en servir. Ce dernier point ne démontre pas l’échec du format hybride : il indique un besoin d’accompagnement à vérifier. La synthèse attendue doit articuler ces limites, attribuer les affirmations et proposer des conditions de suivi, plutôt que distribuer artificiellement les sources entre un camp moderne et un camp conservateur.',
 grammar='Use attribution and concessive qualification to integrate non-equivalent sources. Do not add numerical comparability where the dossier supplies none; an anticipated effect and an observed pedagogical requirement have different status.',
 model='Si l’économie de déplacements paraît plausible, elle ne résume pas la qualité de l’atelier.',translation='While reduced travel seems plausible, it does not sum up workshop quality.',
 question='Why is a single aggregate conclusion risky?',choices=['The sources address different outcomes and evidential statuses','All sources use identical measures','Pedagogical concerns have been disproved'],
 grammar_question='What is the function of si in the model?',grammar_choices=['A concessive acknowledgement of plausibility','A guarantee that savings are measured','A past counterfactual claim'],
 script='Directrice : Faut-il attendre d’avoir tout mesuré ? Intervenante : Non, mais il faut dire ce que l’essai permettrait d’apprendre. Représentant : Et prévoir comment participer sans équipement personnel. Directrice : Nous pourrions limiter l’essai à deux activités, avec un accès accompagné sur place. Intervenante : À condition que le bilan distingue l’accès, la participation et les apprentissages.',
 listen_question='What condition accompanies the proposed trial?',listen_choices=['Evaluate access, participation and learning separately','Assume all learning effects are equal','Require everyone to own equipment'],
 cross_question='Which recommendation fits all three concerns?',cross_choices=['A limited supported trial with distinct evaluation dimensions','A blanket hybrid conversion justified only by travel savings','No decision until every uncertainty disappears'],quote='ce que l’essai permettrait d’apprendre',quote_prompt='Copy the exact clause identifying the learning purpose of the trial.',
 words=[('des dimensions qui ne se confondent pas','dimensions that must not be conflated','Des aspects différents qu’un même indicateur ne représente pas entièrement.'),('un accès numérique accompagné sur place','supported on-site digital access','Une possibilité d’utiliser les outils avec une aide dans le lieu concerné.'),('attribuer les affirmations aux sources','to attribute claims to their sources','Indiquer clairement qui avance chaque proposition.')],
 transfer='Write a 400–460-word decision brief synthesising the dossier with limitations and a justified conditional proposal. Add an 80-word public explanation without technical jargon. Defend the recommendation orally under two conflicting objections. Review source fidelity, integration, audience adaptation and precision separately; this formative dossier does not certify C1.'),
dict(id='c2-05',title='Interpret humour and stance in a public discussion',
 reading='Dans une émission fictive, une intervenante salue un nouveau formulaire « si simple qu’il mérite désormais sa propre formation ». La formule peut faire rire parce qu’elle rapproche une promesse de simplicité d’un dispositif qui semble la démentir. Elle ne constitue pas à elle seule un bilan des usages. Un second invité répond que la formation a précisément permis à de nouveaux publics de participer. Il ne réfute pas nécessairement l’ironie ; il déplace le critère d’évaluation, de la simplicité intrinsèque vers la possibilité d’un apprentissage accompagné. L’animateur résume : « Vous êtes donc d’accord sur l’échec. » Cette synthèse force une convergence que les propos n’établissent pas. Une écoute fine doit reconnaître l’effet humoristique, la concession possible et le changement de critère, sans décider que l’un des locuteurs dit secrètement le contraire de tout ce qu’il affirme.',
 grammar='Irony can target one implication without reversing every proposition. Distinguish a humorous echo, a change in evaluation criterion and an attributed consensus. Modal commitment survives changes of register.',
 model='Qu’une formation soit utile ne suffit pas à rendre le formulaire intrinsèquement simple.',translation='That training is useful is not sufficient to make the form intrinsically simple.',
 question='What does the second guest mainly change?',choices=['The criterion, towards supported participation','Every factual claim made by the first guest','The topic to an unrelated personal anecdote'],
 grammar_question='What logical scope does ne suffit pas preserve?',grammar_choices=['Usefulness is insufficient evidence of intrinsic simplicity','Training must be useless','The form is proved inaccessible to everyone'],
 script='Animatrice : Un progrès, alors ? Invitée : Si vous appelez progrès le fait de mieux expliquer une difficulté qu’on promettait de supprimer, oui ; mais gardons les deux idées distinctes. Invité : Et reconnaissons que mieux expliquer change réellement la situation de certains usagers. Invitée : Certainement. Mon ironie ne leur retire pas ce bénéfice. Elle interroge la promesse initiale.',
 listen_question='What does the first guest explicitly concede?',listen_choices=['Explanation can bring a real benefit to some users','The initial simplicity promise is fully fulfilled','Her irony denies every benefit'],
 cross_question='Which mediation preserves the nuanced exchange?',cross_choices=['A real supported-access benefit can coexist with criticism of the original promise','Both guests prove universal failure','The disagreement is only personal hostility'],quote='la promesse initiale',quote_prompt='Copy the precise object of the final criticism.',
 words=[('un critère d’évaluation déplacé','a shifted evaluation criterion','Un changement de ce à partir de quoi l’on juge une situation.'),('une convergence indûment attribuée','an unduly attributed convergence','Un accord présenté comme établi alors que les propos ne le démontrent pas.'),('un bénéfice que l’ironie ne nie pas','a benefit the irony does not deny','Un avantage qui reste reconnu malgré la critique humoristique.')],
 transfer='Listen first without the script and annotate tone, target of humour and changes of commitment. Write 450–520 French words comparing two plausible readings and delimit the evidence for each. Mediate orally without humour for one audience, then with a restrained rhetorical contrast for another. Synthetic performance cannot validate spontaneous prosodic comprehension; obtain qualified human review.'),
dict(id='c2-06',title='Handle a deliberately ambiguous invitation',
 reading='Une institution invite ses partenaires à une consultation en précisant qu’ils sont « entièrement libres de contribuer à l’élaboration du projet ». Selon le contexte, la formule peut souligner une absence d’obligation ou insister sur une possibilité de participation. Une partenaire y entend cependant que les choix essentiels sont déjà arrêtés : elle relève que les contributions portent sur l’élaboration d’un projet nommé, non sur l’opportunité de ce projet. Cette lecture est plausible, mais ne saurait devenir sans examen une preuve d’intention manipulatrice. Le responsable précise que certaines contraintes financières sont fixées, alors que les usages restent discutables. La conversation doit alors traiter des degrés réels d’ouverture, plutôt que débattre seulement de la sincérité d’un adjectif. Réparer l’ambiguïté consiste à nommer ce qui est décidé, ce qui est négociable et ce qu’une contribution pourrait effectivement modifier.',
 grammar='Distinguish semantic possibility, pragmatic implication and inferred intent. A clarification can narrow an interpretation without proving it was irrational; quantifiers such as entièrement do not remove contextual constraints.',
 model='La formule ouvre une possibilité sans préciser ce que la participation pourra modifier.',translation='The wording opens a possibility without specifying what participation can change.',
 question='Which inference stays within the dossier?',choices=['The practical scope of participation needs clarification','Manipulative intent is established','Every project constraint is negotiable'],
 grammar_question='Which formulation best repairs scope ambiguity?',grammar_choices=['Le budget est fixé ; les usages restent à discuter.','Vous êtes libres, donc toute objection est sans objet.','Tout est ouvert, sauf ce qui ne l’est pas.'],
 script='Partenaire : Si je conteste le projet lui-même, ma contribution a-t-elle encore sa place ? Responsable : Oui, mais elle ne suspendra pas le calendrier déjà voté. Partenaire : Alors distinguons être entendue et pouvoir infléchir la décision. Responsable : Vous avez raison ; nous devons expliquer comment chaque contribution recevra une réponse et quelles marges demeurent.',
 listen_question='Which distinction is negotiated?',listen_choices=['Being heard versus being able to change the decision','Courtesy versus the ability to speak French','A fixed calendar versus a cancelled consultation'],
 cross_question='Which follow-up would test the clarification constructively?',cross_choices=['Ask what a contribution could change and how a response will be given','Declare intent proven from one adjective','Assume every objection halts the calendar'],quote='infléchir la décision',quote_prompt='Copy the exact phrase naming an influence stronger than merely being heard.',
 words=[('les degrés réels d’ouverture','the actual degrees of openness','Les aspects qui peuvent effectivement encore être discutés.'),('une intention qu’on ne peut établir','an intention one cannot establish','Un dessein qui n’est pas démontré par les éléments disponibles.'),('expliciter les marges de décision','to make decision-making latitude explicit','Préciser ce qui peut encore être choisi ou modifié.')],
 transfer='Prepare a 450-word analysis of the ambiguity with an alternative interpretation and limits on inferred intent. Negotiate spontaneously with the Tutor: ask a difficult scope question, respond to an evasive answer and summarise a precise clarification. Produce two reformulations for partners and the public. Human review must assess flexibility, pragmatic accuracy and register.'),
dict(id='c2-08',title='C2 review: mediate a disputed museum narrative',
 reading='Un musée fictif prépare une exposition sur les transformations d’un quartier. Le texte de présentation affirme vouloir « rendre enfin leur place aux mémoires ordinaires ». Une historienne apprécie l’élargissement des témoignages, mais s’interroge sur le présupposé contenu dans enfin : la formule risque d’effacer le travail associatif antérieur pour mieux mettre en scène une réparation institutionnelle. Une médiatrice répond que le public a besoin d’une entrée lisible, non d’un inventaire de toutes les précautions historiographiques. Ces deux positions ne portent pas seulement sur le nombre de mots du panneau. Elles interrogent l’attribution d’une initiative, la visibilité des médiations et la manière dont une institution se présente comme sujet d’une restitution. Une synthèse fidèle ne doit ni réduire la critique à une querelle lexicale ni traiter une exigence de lisibilité comme un refus d’histoire complexe.',
 grammar='Analyse presupposition, agency and rhetorical framing while distinguishing critique from allegations of intent. Concede a practical need without treating it as sufficient to settle attribution.',
 model='La lisibilité est nécessaire ; elle ne dispense pas d’expliciter ce que le récit attribue à l’institution.',translation='Readability is necessary; it does not remove the need to make the narrative’s attribution to the institution explicit.',
 question='What is the historian’s central concern?',choices=['The framing may obscure earlier associative work','Ordinary testimony must be excluded','Every short display text is necessarily false'],
 grammar_question='Which concession preserves the dispute’s scope?',grammar_choices=['Reconnaître le besoin de lisibilité sans effacer l’enjeu d’attribution.','La lisibilité prouve que toute critique est inutile.','Toute simplification interdit toute exposition.'],
 script='Médiatrice : Je peux retirer enfin, mais le problème disparaîtra-t-il avec le mot ? Historienne : Pas forcément. Si le musée reste le seul acteur du récit, l’effet peut subsister. Habitante : Nous voulons surtout que le visiteur sache d’où viennent les paroles qu’il lit. Médiatrice : Alors nommons les collectifs et distinguons le témoignage, le choix éditorial et le commentaire du musée.',
 listen_question='What constructive proposal emerges?',listen_choices=['Make sources and editorial roles visible','Remove every testimony','Assume removing one word resolves the whole issue'],
 cross_question='Which final synthesis respects the dossier?',cross_choices=['Combine accessible presentation with explicit attribution and editorial mediation','Treat the dispute as proof of deliberate historical fraud','Present testimony as unmediated institutional speech'],quote='le choix éditorial',quote_prompt='Copy the exact phrase naming the selection layer between testimony and museum commentary.',
 words=[('une réparation institutionnelle mise en scène','a staged institutional act of redress','Une manière de présenter publiquement l’institution comme réparatrice.'),('rendre visibles les médiations du récit','to make narrative mediation visible','Montrer comment les paroles sont choisies, présentées et commentées.'),('un enjeu d’attribution historique','an issue of historical attribution','Une question portant sur les acteurs auxquels une action est rapportée.')],
 transfer='Write a 520–620-word critical synthesis that integrates source roles, an alternative interpretation and the limits of each inference. Add a 90-word museum panel and an 90-word note to contributors; justify the different registers. Defend choices in a sustained oral exchange with contradictory challenges. Assess pragmatic nuance, source fidelity, organisation and precise reformulation separately; this is not a C2 certification exam.'),
]

def build(row):
    stage,number=row['id'].split('-');level=stage.upper();version='0.7.'+str(int(number))
    identity=row['id']+'-'+version
    def uid(key):return str(uuid5(NAMESPACE_URL,'fluentloop-completion-'+identity+'-'+key))
    def choice(key,prompt,options,explanation,kind='multiple_choice',data=None,offset=0):
        index=(int(number)+offset)%3;labels=list(options);labels.insert(index,labels.pop(0))
        return dict(key=key,type=kind,prompt=prompt,instructions='Use the supplied fictional source; distinguish what is stated, inferred and not established.',
            options=labels,correct_option=index,explanation=explanation,data=data or {})
    left=[dict(id=uid(f'l{i}'),text=fr) for i,(fr,_,_) in enumerate(row['words'])]
    right=[dict(id=uid(f'r{i}'),text=en) for i,(_,en,_) in enumerate(row['words'])]
    reading_explanation=row['choices'][0]+'. Source: '+row['reading']
    if len(reading_explanation)>1000:reading_explanation=row['choices'][0]+'. '+row['grammar']
    reading=[choice('read-meaning',row['question'],row['choices'],reading_explanation),
        choice('grammar-scope',row['grammar_question'],row['grammar_choices'],row['grammar'],offset=1),
        dict(key='contextual-vocabulary',type='matching',prompt='Match the contextual expressions with their meanings.',instructions='Use each meaning once; these are contextual definitions.',
            data=dict(left_items=left,right_items=list(reversed(right)),answer_pairs={a['id']:b['id'] for a,b in zip(left,right)}),explanation='; '.join(f'{fr} — {en}' for fr,en,_ in row['words']))]
    listening=[choice('listen-position',row['listen_question'],row['listen_choices'],row['listen_choices'][0]+'. Script: '+row['script'],kind='listening',data={'text_fr':row['script']},offset=2),
        choice('integrate-sources',row['cross_question'],row['cross_choices'],row['cross_choices'][0]+'. Compare the reading and listening sources.',offset=1),
        dict(key='locate-phrase',type='short_answer',prompt=row['quote_prompt'],instructions='Transcript available in this lesson: copy the exact requested phrase. This item checks location/spelling, not open-ended interpretation.',
            data={'accepted_answers':[row['quote']]},explanation='Exact source phrase: '+row['quote'])]
    assert row['quote'] in row['script'],row['id']
    tasks=[dict(key='read-and-notice',skill='grammar',module_title=row['title'],title=row['title']+': read and notice',objective=row['grammar'],
        context=row['reading'],vocabulary=[w[0] for w in row['words']],estimated_minutes=25,exercises=reading,
        grammar=[dict(slug='completion-'+row['id'],title=row['title'],summary=row['grammar'],rule_code='completion-'+row['id'],explanation_english=row['grammar'],examples=[(row['model'],row['translation'])])]),
        dict(key='listen-and-integrate',skill='reading',module_title=row['title'],title=row['title']+': listen and integrate',
        objective='Identify details, stance and limits of commitment in the scripted exchange, then integrate both sources.',
        context='Original scripted exchange for listening and transcript-assisted review. One synthetic voice may perform every role; this does not demonstrate spontaneous multi-speaker comprehension.\n\n'+row['script'],
        exercises=listening,estimated_minutes=25,prerequisites=['read-and-notice']),
        dict(key='transfer-and-assess',skill='writing',module_title=row['title'],title=row['title']+': transfer and assess',
        objective='Transfer the module language to an unfamiliar situation and review comprehension, writing and interaction separately.',
        context=row['transfer']+'\n\nRevision: retrieve the three contextual expressions without the model on a later day; correct saved errors and reuse them in a new scenario.\n\nReview task fulfilment, source fidelity, grammar, vocabulary, organisation and interaction/repair separately. Treat spelling extraction as supported practice, not proficiency evidence. Optional AI feedback is advisory. Independent human language/phonetic review and empirical calibration remain pending.',
        exercises=[],estimated_minutes=40,prerequisites=['read-and-notice','listen-and-integrate'])]
    return dict(version=version,level=level,status='draft',title=level+' module completion: '+row['title'],
        source_license='Original AI-assisted module drafts. Qualified independent linguistic, pedagogical, phonetic, answer-key and CEFR reviews pending.',
        glossary=[dict(lemma=fr,part_of_speech='phrase',translation=en,definition_french=definition) for fr,en,definition in row['words']],tasks=tasks)

if __name__=='__main__':
    import sys
    sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
    from app.assessment_content import AssessmentPack
    folder=Path(__file__).resolve().parents[1]/'content/completion';folder.mkdir(exist_ok=True)
    for row in MODULES:
        pack=AssessmentPack.model_validate(build(row))
        file=folder/(row['id']+'-completion-'+pack.version+'.json')
        body=pack.model_dump_json(indent=2)+'\n'
        if file.exists():
            assert file.read_text(encoding='utf-8')==body,'A release is immutable; increment its version before revising.'
        else:file.write_text(body,encoding='utf-8')
    print('Authored 17 modules: 51 staged lessons,102 scored exercises,17 open writing/speaking tasks; no database access.')
